            repository: repoInfo
        });
        var st = provider.prStatus(prNumber);
        return !!st && st.checkConclusion === 'green';
    } catch (e) {
        console.warn('  ⚠️  latch-skip rollup probe failed: ' + (e.message || e));
        return false;
    }
}

