        sm.action(baseParams('epam', 'dmtools-dart', [armRule()]));

        assert.equal(sm.capturedPrLabelAdds.length, 1, 'legacy PRs keep today\u2019s behavior');
        assert.equal(sm.capturedPrLabelAdds[0].labels.join(','), 'agent:rework');
    });
});

