 */
function parseVerdictRecords(comments) {
    var list = Array.isArray(comments) ? comments : [];
    var records = [];
    for (var i = 0; i < list.length; i++) {
        var rec = extractVerdictRecord(list[i] && list[i].body);
        if (!rec) continue;
        rec.order = i;
