            { body: rv.MARKER_PREFIX + '{"head":"h1","verdict":"APPROVE","blocking":0,"important":0,"suggestions":1,"at":"2026-10-09T05:47:30.000Z","source":"pr_review.json"}' + rv.MARKER_SUFFIX }
