        assert.equal(records.length, 1, 'exactly the marker comment parses');
        assert.equal(records[0].verdict, 'APPROVE');
        assert.equal(records[0].head, 'h1');
        assert.equal(records[0].suggestions, 1, 'thread census rides the record');
    });

